WITH scored AS (SELECT *, MIN(discount_pct) OVER (PARTITION BY channel) AS channel_min_discount_pct, AVG(discount_pct) OVER (PARTITION BY channel ORDER BY discount_pct, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS discount_pct_avg_3_prior, NTILE(5) OVER (PARTITION BY promo_code, channel ORDER BY discount_pct, id) AS discount_pct_bucket, LAST_VALUE(channel, TRUE) OVER (PARTITION BY channel ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_channel, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY discount_pct, id) AS seq_no FROM promotions) SELECT id, promo_code, starts_on, discount_pct_avg_3_prior, discount_pct_bucket, last_known_channel, seq_no, CASE WHEN promo_code RLIKE '^(SPRING10|WELCOME5)$' THEN 'EXTENDED' ELSE 'GROUP_B' END AS promo_code_zone FROM scored ORDER BY promo_code NULLS LAST
